// Determines whether the incoming item is a transport failure (an ERROR
// payload from 03-http-executor, stage "http_executor") or a genuine
// HTTP Response Contract, and confirms whichever shape it claims to be
// is actually well-formed. This is the only node that validates input
// shape - every later node trusts __kind and the fields it implies.
const STAGE = 'response_normalizer';
const WORKFLOW_VERSION = '1.0';

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_HTTP_RESPONSE_CONTRACT',
    'Input to the Response Normalizer must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

if (item.status === 'ERROR') {
  // A transport failure from the HTTP Executor (timeout, connection
  // refused, DNS failure, pre-flight validation failure, ...) - this
  // workflow's whole job is to normalize exactly this into a transport
  // category, not to pass it through untouched the way 01/02/03 pass
  // through an upstream error that isn't theirs to handle. It still has
  // to look like a well-formed shared Error Payload first.
  const requiredErrorFields = ['status', 'stage', 'code', 'message', 'details', 'timestamp', 'workflow_version'];
  const missing = requiredErrorFields.filter((f) => item[f] === undefined);
  if (missing.length > 0) {
    return { json: errorPayload(
      'INVALID_HTTP_RESPONSE_CONTRACT',
      `Upstream ERROR payload is missing required field(s): ${missing.join(', ')}`,
      { missing_fields: missing }
    ) };
  }
  return { json: { ...item, __kind: 'error' } };
}

const requiredFields = [
  'workflow_version', 'contract_version', 'request_id', 'response_id',
  'status_code', 'headers', 'body', 'latency_ms', 'timestamps', 'request',
  'expected', 'test_case', 'metadata'
];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_HTTP_RESPONSE_CONTRACT',
    `HTTP Response Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields, request_id: item.request_id || null }
  ) };
}

return { json: { ...item, __kind: 'response' } };

// Maps whatever transport result actually happened - a real HTTP
// response, or a transport-level failure from the HTTP Executor - into
// exactly one of a fixed set of categories the Decision Agent can branch
// on without knowing which HTTP client, error code, or status range
// produced it. No AI, no inference, no PASS/FAIL judgment - a status
// code is categorized here, never compared against `expected`.
const STAGE = 'response_normalizer';
const WORKFLOW_VERSION = '1.0';

// Every 03-http-executor error code this workflow knows how to
// categorize. Hand-kept in sync with that workflow's own error-code
// table (docs/contracts/error-payload.md, http_executor section) - same
// convention as SUPPORTED_VERIFICATION_TYPES/AGENT_ROUTES in
// 01-ingestion.json (docs/workflow-standards.md). A code with no entry
// here is a real drift signal, not silently guessed - see
// UNKNOWN_TRANSPORT_ERROR below.
const TRANSPORT_CODE_MAP = {
  TIMEOUT_ERROR: 'TIMEOUT',
  CONNECTION_REFUSED: 'NETWORK_ERROR',
  DNS_RESOLUTION_FAILED: 'NETWORK_ERROR',
  NETWORK_ERROR: 'NETWORK_ERROR',
  INVALID_URL: 'NETWORK_ERROR',
  MISSING_CREDENTIALS: 'AUTHENTICATION_ERROR',
  UNSUPPORTED_AUTHENTICATION: 'AUTHENTICATION_ERROR',
  UNSUPPORTED_HTTP_METHOD: 'UNKNOWN_ERROR',
  INVALID_API_REQUEST_CONTRACT: 'UNKNOWN_ERROR'
};

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (!item.__kind) {
  return { json: item };
}

if (item.__kind === 'error') {
  const transportStatus = TRANSPORT_CODE_MAP[item.code];
  if (!transportStatus) {
    return { json: errorPayload(
      'UNKNOWN_TRANSPORT_ERROR',
      `HTTP Executor error code "${item.code}" has no known transport category mapping`,
      { code: item.code, request_id: (item.details && item.details.request_id) || null }
    ) };
  }
  return { json: { ...item, __transport: { status: transportStatus, status_code: null, response_time_ms: null } } };
}

const statusCode = item.status_code;

if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
  return { json: errorPayload(
    'INVALID_STATUS_CODE',
    `status_code must be an integer between 100 and 599, received "${statusCode}"`,
    { request_id: item.request_id, status_code: statusCode }
  ) };
}

let transportStatus;
if (statusCode === 401 || statusCode === 403) transportStatus = 'AUTHENTICATION_ERROR';
else if (statusCode >= 200 && statusCode <= 299) transportStatus = 'SUCCESS';
else if (statusCode >= 400 && statusCode <= 499) transportStatus = 'CLIENT_ERROR';
else if (statusCode >= 500 && statusCode <= 599) transportStatus = 'SERVER_ERROR';
else transportStatus = 'UNKNOWN_ERROR'; // a valid status code (1xx/3xx) with no specific category

return { json: { ...item, __transport: {
  status: transportStatus,
  status_code: statusCode,
  response_time_ms: typeof item.latency_ms === 'number' ? item.latency_ms : null
} } };

// Produces a stable `headers` object for the final contract - always a
// plain object, never omitted, never exposing raw n8n/HTTP Request node
// internals. A transport failure never received real response headers,
// so its normalized headers are always {} (explicit, not omitted).
const STAGE = 'response_normalizer';
const WORKFLOW_VERSION = '1.0';

const item = $input.item.json;

if (!item.__kind) {
  return { json: item };
}

if (item.__kind === 'error') {
  return { json: { ...item, __normalized_headers: {} } };
}

if (typeof item.headers !== 'object' || item.headers === null || Array.isArray(item.headers)) {
  return { json: {
    status: 'ERROR',
    stage: STAGE,
    code: 'MALFORMED_RESPONSE',
    message: `HTTP Response Contract headers for request_id "${item.request_id}" must be a JSON object`,
    details: { request_id: item.request_id },
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  } };
}

return { json: { ...item, __normalized_headers: item.headers } };

// Produces a stable `body` value for the final contract - whatever
// shape the target API returned, passed through as-is (this workflow
// never parses, reshapes, or judges body content, same non-goal as
// 03-http-executor). A transport failure never received a body, so its
// normalized body is always null (explicit, not omitted). The only
// failure this node can produce is a body that can't even be carried
// through n8n's JSON item data (e.g. a circular structure).
const STAGE = 'response_normalizer';
const WORKFLOW_VERSION = '1.0';

const item = $input.item.json;

if (!item.__kind) {
  return { json: item };
}

if (item.__kind === 'error') {
  return { json: { ...item, __normalized_body: null } };
}

try {
  JSON.stringify(item.body);
} catch (err) {
  return { json: {
    status: 'ERROR',
    stage: STAGE,
    code: 'MALFORMED_RESPONSE',
    message: `Response body for request_id "${item.request_id}" could not be normalized: ${err.message}`,
    details: { request_id: item.request_id },
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  } };
}

return { json: { ...item, __normalized_body: item.body !== undefined ? item.body : null } };

// Produces the final contract's metadata block. Kept as its own node,
// even though the job is small, so the workflow's node graph matches
// the one-job-per-node convention (docs/workflow-standards.md) and the
// task's requested node chain.
const item = $input.item.json;

if (!item.__kind) {
  return { json: item };
}

return { json: { ...item, __normalized_metadata: {
  normalized_at: new Date().toISOString(),
  source_workflow: '03-http-executor',
  next_workflow: '05-decision-agent'
} } };

// Final assembly: produces the Normalized Response Contract
// (docs/contracts/normalized-response-contract.md) from everything the
// previous nodes computed. This is the only node that builds the final
// output shape - earlier nodes only ever add __-prefixed working fields
// or short-circuit with this workflow's own ERROR payload, never the
// public contract fields themselves. Never compares transport.status_code
// against `expected`, never sets a PASS/FAIL verdict, never calls an AI
// model - that is the Decision Agent's job (docs/architecture/
// milestone-1.md section 5), not this workflow's.
const CONTRACT_VERSION = '1.0';
const NORMALIZER_WORKFLOW_VERSION = '1.0';

const item = $input.item.json;

if (!item.__kind) {
  return { json: item };
}

const isError = item.__kind === 'error';

return { json: {
  workflow_version: NORMALIZER_WORKFLOW_VERSION,
  contract_version: CONTRACT_VERSION,
  request_id: isError ? ((item.details && item.details.request_id) || null) : item.request_id,
  response_id: isError ? null : item.response_id,
  test_case: isError ? ((item.details && item.details.test_case) || null) : item.test_case,
  expected: isError ? ((item.details && item.details.expected) || null) : item.expected,
  transport: item.__transport,
  response: {
    headers: item.__normalized_headers,
    body: item.__normalized_body
  },
  metadata: item.__normalized_metadata
} };
